SET NAMES utf8mb4;
USE bcd_application2;
START TRANSACTION;

UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"INFORMED CONSENT FORM","projectDetails":{"projectTitle":{"label":"Title of Project","value":"AI Enabled Breast Cancer Risk Prediction Tool"},"iecReference":{"label":"IEC Reference Number","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"IEC Approval Date","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"IEC Approval Duration","value":"Until Mar 2028"}},"sections":[{"heading":"Voluntary Participation","paragraphs":[{"text":"Your participation in this study is voluntary. You may refuse to participate in this study or in any part of this study at any time. Likewise the investigator also retains the right to terminate your participation in the experiment at any time without giving a reason. The decision to withdraw or terminate your participation will not affect your relations with your institute/university/hospital or affect the care you receive. You are encouraged to ask questions about this study any time during the study."}]},{"heading":"Information collected as part of this study","paragraphs":[{"text":"Demographics, lifestyle, family history, menstrual and reproductive health information - necessary"},{"text":"Mammograms along with report (necessary)"},{"text":"ultrasound and/or biopsy report (optional)"}]},{"heading":"Confidentiality and Data Protection","paragraphs":[{"text":"Data Anonymization: All information gathered in this study will be collected, processed, and stored in an irreversibly anonymized manner to ensure your privacy. Collected information storage adheres to the Digital Personal Data Protection (DPDP) Act standards."},{"text":"The data collected will be used in future research, including the development of other foundation models."},{"text":"Rights: You have the right to access and correct your personal data and to withdraw your consent for research processing at any time. The decision to withdraw will not affect the regular clinical care you receive."},{"text":"Retention: Your irreversibly anonymized data and samples may be stored for as long as they are useful for lawful research and required safeguards are in place, in accordance with the DPDP Act and other legal or regulatory obligations."},{"text":"If you wish to speak to someone independent of the study as well as withdrawal of the consent, you may contact the Institutional Ethics Committee (IEC)"},{"text":"Name: Dr. Sri Vidya Jagadish, Secretary, IEC, TANUH"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"Participant Consent","declaration":"I have read and understood the participation information sheet and confirmed to participate in this study voluntarily. I have had the opportunity to ask questions, and all my questions have been answered to my satisfaction. I understand that I have the right to withdraw my consent and refuse to participate at any time. I give my consent to be part of this study.","ageCheckboxLabel":"I am 18 years of age or older","voluntaryCheckboxLabel":"The information needed for this study is being provided voluntarily"}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='en';
UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"सूचना दी गई सहमति फॉर्म","projectDetails":{"projectTitle":{"label":"परियोजना का शीर्षक","value":"स्तन कैंसर के जोखिम की भविष्यवाणी करने के लिए AI सक्षम उपकरण"},"iecReference":{"label":"आईईसी संदर्भ संख्या","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"आईईसी अनुमोदन की तिथि","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"आईईसी अनुमोदन की अवधि","value":"मार्च 2028 तक"}},"sections":[{"heading":"स्वैच्छिक भागीदारी","paragraphs":[{"text":"इस अध्ययन में आपकी भागीदारी स्वैच्छिक है. आप इस अध्ययन में या इस अध्ययन के किसी भी भाग में किसी भी समय भाग लेने से इनकार कर सकते हैं। इसी तरह शोधकर्ता को भी किसी भी समय बिना किसी कारण दिए प्रयोग में आपकी भागीदारी समाप्त करने का अधिकार सुरक्षित है। अपनी भागीदारी को वापस लेने या समाप्त करने का निर्णय आपके संस्थान / विश्वविद्यालय / अस्पताल के साथ आपके संबंधों को प्रभावित नहीं करेगा या आपको प्राप्त देखभाल को प्रभावित नहीं करेगा। आपको इस अध्ययन के दौरान किसी भी समय इस अध्ययन के बारे में प्रश्न पूछने के लिए प्रोत्साहित किया जाता है।"}]},{"heading":"इस अध्ययन के अंतर्गत एकत्रित जानकारी","paragraphs":[{"text":"जनसांख्यिकीय, जीवन शैली, पारिवारिक इतिहास, मासिक धर्म और प्रजनन स्वास्थ्य जानकारी - आवश्यक"},{"text":"रिपोर्ट के साथ मैमोग्राम (आवश्यक)"},{"text":"अल्ट्रासाउंड और/या बायोप्सी रिपोर्ट (वैकल्पिक)"}]},{"heading":"गोपनीयता और डेटा संरक्षण","paragraphs":[{"text":"डेटा अनामितकरणः इस अध्ययन में एकत्र की गई सभी जानकारी आपकी गोपनीयता सुनिश्चित करने के लिए अपरिवर्तनीय रूप से अनामित तरीके से एकत्र की जाएगी, संसाधित की जाएगी और संग्रहीत की जाएगी। एकत्रित जानकारी भंडारण डिजिटल व्यक्तिगत डेटा संरक्षण (डीपीडी) अधिनियम के मानकों का पालन करता है।"},{"text":"एकत्रित डेटा का उपयोग भविष्य के अनुसंधान में किया जाएगा, जिसमें अन्य फाउंडेशन मॉडल का विकास भी शामिल है।"},{"text":"अधिकारः आपके पास अपने व्यक्तिगत डेटा तक पहुँचने और सुधारने और अनुसंधान प्रसंस्करण के लिए अपनी सहमति को किसी भी समय वापस लेने का अधिकार है। वापस लेने का निर्णय आपको प्राप्त नियमित नैदानिक देखभाल को प्रभावित नहीं करेगा।"},{"text":"भंडारणः आपके अनिश्चित रूप से अज्ञात डेटा और नमूने तब तक संग्रहीत किए जा सकते हैं जब तक वे वैध अनुसंधान के लिए उपयोगी हों और आवश्यक सुरक्षा उपाय लागू हों, डीपीडीपी अधिनियम और अन्य कानूनी या नियामक दायित्वों के अनुसार।"},{"text":"यदि आप अध्ययन से स्वतंत्र किसी व्यक्ति से बात करना चाहते हैं और सहमति वापस लेना चाहते हैं, तो आप संस्थागत नैतिकता समिति (IEC) से संपर्क कर सकते हैं"},{"text":"नाम: डॉ. श्री विद्या जगदीश, सचिव, आईईसी, तनुह"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"प्रतिभागियों की सहमति","declaration":"मैंने सहभागिता सूचना पत्र पढ़ लिया और समझा और इस अध्ययन में स्वेच्छा से भाग लेने की पुष्टि की। मुझे प्रश्न पूछने का अवसर मिला और मेरे सभी प्रश्नों का मेरे संतुष्टि के लिए उत्तर दिया गया। मुझे समझ में आता है कि मुझे अपनी सहमति वापस लेने और किसी भी समय भाग लेने से इनकार करने का अधिकार है। मैं इस अध्ययन का हिस्सा बनने के लिए अपनी सहमति देता हूं।","ageCheckboxLabel":"मैं 18 वर्ष या उससे अधिक की आयु का हूँ","voluntaryCheckboxLabel":"इस अध्ययन के लिए आवश्यक जानकारी स्वेच्छा से दी जा रही है"}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='hi';
UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"তথ্যপ্রাপ্ত সম্মতি ফর্ম","projectDetails":{"projectTitle":{"label":"প্রকল্পের শিরোনাম","value":"এআই-এ সক্ষম স্তন ক্যান্সারের ঝুঁকি পূর্বাভাস সরঞ্জাম"},"iecReference":{"label":"আইইসি রেফারেন্স নম্বর","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"আইইসি অনুমোদনের তারিখ","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"আইইসি অনুমোদনের সময়কাল","value":"২০২৮ সালের মার্চ পর্যন্ত"}},"sections":[{"heading":"স্বেচ্ছায় অংশগ্রহণ","paragraphs":[{"text":"এই গবেষণায় আপনার অংশগ্রহণ স্বেচ্ছায়। আপনি যে কোনও সময় এই গবেষণায় বা এই গবেষণার যে কোনও অংশে অংশগ্রহণ করতে অস্বীকার করতে পারেন। একইভাবে গবেষক কোনও কারণ না দিয়ে যে কোনও সময় পরীক্ষায় আপনার অংশগ্রহণ বন্ধ করার অধিকারও সংরক্ষণ করেন। আপনার অংশগ্রহণ প্রত্যাহার বা সমাপ্তির সিদ্ধান্ত আপনার ইনস্টিটিউট / বিশ্ববিদ্যালয় / হাসপাতালের সাথে আপনার সম্পর্ককে প্রভাবিত করবে না বা আপনার দেওয়া যত্নকে প্রভাবিত করবে না। আপনাকে এই গবেষণার সময় যে কোনও সময় এই গবেষণার বিষয়ে প্রশ্ন জিজ্ঞাসা করতে উত্সাহিত করা হয়।"}]},{"heading":"এই গবেষণার অংশ হিসেবে সংগৃহীত তথ্য","paragraphs":[{"text":"জনসংখ্যা, জীবনধারা, পারিবারিক ইতিহাস, ঋতু ও প্রজনন স্বাস্থ্য সংক্রান্ত তথ্য - প্রয়োজনীয়"},{"text":"রিপোর্ট সহ ম্যামোগ্রাফি (প্রয়োজনীয়)"},{"text":"আল্ট্রাসাউন্ড এবং/অথবা বায়পসি রিপোর্ট (ঐচ্ছিক)"}]},{"heading":"গোপনীয়তা ও তথ্য সুরক্ষা","paragraphs":[{"text":"ডেটা অ্যানোনিমাইজেশনঃ এই গবেষণায় সংগৃহীত সমস্ত তথ্য আপনার গোপনীয়তা নিশ্চিত করার জন্য অনিবার্যভাবে অ্যানোনিমাইজড উপায়ে সংগ্রহ, প্রক্রিয়াজাত এবং সংরক্ষণ করা হবে। সংগৃহীত তথ্য সংরক্ষণ ডিজিটাল ব্যক্তিগত তথ্য সুরক্ষা (ডিপিডিপি) আইন মান মেনে চলে।"},{"text":"সংগ্রহ করা তথ্য ভবিষ্যতে গবেষণায় ব্যবহার করা হবে, যার মধ্যে রয়েছে অন্যান্য ফাউন্ডেশন মডেলের উন্নয়ন।"},{"text":"অধিকারঃ আপনার ব্যক্তিগত তথ্য অ্যাক্সেস এবং সংশোধন করার এবং গবেষণা প্রক্রিয়াকরণের জন্য আপনার সম্মতি যে কোনও সময় প্রত্যাহার করার অধিকার রয়েছে। প্রত্যাহারের সিদ্ধান্ত আপনার নিয়মিত ক্লিনিকাল যত্নের উপর প্রভাব ফেলবে না।"},{"text":"সংরক্ষণঃ আপনার অনিবার্যভাবে অজ্ঞাত তথ্য এবং নমুনাগুলি যতক্ষণ পর্যন্ত আইনী গবেষণার জন্য দরকারী এবং প্রয়োজনীয় সুরক্ষা ব্যবস্থা রয়েছে ততক্ষণ সংরক্ষণ করা যেতে পারে, ডিপিডিপি আইন এবং অন্যান্য আইনী বা নিয়ন্ত্রক বাধ্যবাধকতা অনুসারে।"},{"text":"আপনি যদি গবেষণার স্বাধীন ব্যক্তির সাথে কথা বলতে চান এবং সম্মতি প্রত্যাহার করতে চান, তাহলে আপনি ইন্সটিটিউশনাল ইথিক কমিটির (আইইসি) সাথে যোগাযোগ করতে পারেন।"},{"text":"নামঃ ডঃ শ্রী বিদ্যা জগদীশ, আইইসি, তানুহের সচিব"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"অংশগ্রহণকারীদের সম্মতি","declaration":"আমি অংশগ্রহণের তথ্যপত্র পড়েছি এবং বুঝতে পেরেছি এবং এই গবেষণায় স্বেচ্ছায় অংশগ্রহণের বিষয়টি নিশ্চিত করেছি। আমার প্রশ্ন করার সুযোগ হয়েছে এবং আমার সমস্ত প্রশ্নের উত্তর আমার সন্তুষ্টির জন্য দেওয়া হয়েছে। আমি বুঝতে পারি যে আমার সম্মতি প্রত্যাহার করার এবং যে কোনও সময় অংশগ্রহণ অস্বীকার করার অধিকার আছে। আমি এই গবেষণায় অংশগ্রহণের জন্য আমার সম্মতি দিচ্ছি।","ageCheckboxLabel":"আমার বয়স ১৮ বছর বা তার বেশি","voluntaryCheckboxLabel":"এই গবেষণার জন্য প্রয়োজনীয় তথ্য স্বেচ্ছায় প্রদান করা হচ্ছে"}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='bn';
UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"જાણકારી આપતી સંમતિ ફોર્મ","projectDetails":{"projectTitle":{"label":"પ્રોજેક્ટનું નામ","value":"સ્તન કેન્સરનું જોખમ આગાહી કરવા માટે AI સક્ષમ સાધન"},"iecReference":{"label":"આઇઇસી સંદર્ભ નંબર","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"આઇઇસી મંજૂરી તારીખ","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"આઇઇસી મંજૂરીની અવધિ","value":"માર્ચ 2028 સુધી"}},"sections":[{"heading":"સ્વૈચ્છિક ભાગીદારી","paragraphs":[{"text":"આ અભ્યાસમાં તમારી ભાગીદારી સ્વૈચ્છિક છે. તમે આ અભ્યાસમાં અથવા આ અભ્યાસના કોઈપણ ભાગમાં કોઈપણ સમયે ભાગ લેવાનો ઇનકાર કરી શકો છો. તેવી જ રીતે સંશોધક પણ કોઈ કારણ આપ્યા વિના કોઈપણ સમયે તમારા પ્રયોગમાં ભાગ લેવાનું સમાપ્ત કરવાનો અધિકાર અનામત રાખે છે. તમારી ભાગીદારીને પાછો ખેંચવાનો અથવા સમાપ્ત કરવાનો નિર્ણય તમારી સંસ્થા / યુનિવર્સિટી / હોસ્પિટલ સાથેના તમારા સંબંધોને અસર કરશે નહીં અથવા તમને પ્રાપ્ત સંભાળને અસર કરશે નહીં. તમને અભ્યાસ દરમિયાન કોઈપણ સમયે આ અભ્યાસ વિશે પ્રશ્નો પૂછવા પ્રોત્સાહિત કરવામાં આવે છે."}]},{"heading":"આ અભ્યાસના ભાગરૂપે એકત્રિત કરેલી માહિતી","paragraphs":[{"text":"વસ્તી વિષયક, જીવનશૈલી, પારિવારિક ઇતિહાસ, માસિક સ્રાવ અને પ્રજનન સ્વાસ્થ્ય માહિતી - જરૂરી"},{"text":"રિપોર્ટ સાથે મેમોગ્રામ (જરૂરી)"},{"text":"અલ્ટ્રાસાઉન્ડ અને/અથવા બાયોપ્સી રિપોર્ટ (વૈકલ્પિક)"}]},{"heading":"ગુપ્તતા અને ડેટા રક્ષણ","paragraphs":[{"text":"ડેટા અનામીકરણઃ આ અભ્યાસમાં એકત્રિત થયેલ બધી માહિતી તમારી ગોપનીયતાની ખાતરી કરવા માટે અનિવાર્ય રીતે અનામી રીતે એકત્રિત, પ્રક્રિયા અને સંગ્રહિત કરવામાં આવશે. એકત્રિત કરેલી માહિતી સંગ્રહ ડિજિટલ પર્સનલ ડેટા પ્રોટેક્શન (ડીપીડી) એક્ટના ધોરણોનું પાલન કરે છે."},{"text":"એકત્રિત કરેલા ડેટાનો ઉપયોગ ભવિષ્યના સંશોધનમાં કરવામાં આવશે, જેમાં અન્ય પાયો મોડેલોના વિકાસનો સમાવેશ થાય છે."},{"text":"અધિકારોઃ તમને તમારા વ્યક્તિગત ડેટાની ઍક્સેસ અને સુધારવાનો અને સંશોધન પ્રક્રિયા માટે તમારી સંમતિને કોઈપણ સમયે પાછો ખેંચવાનો અધિકાર છે."},{"text":"જાળવણીઃ તમારા અનિવાર્યપણે અનામીકૃત ડેટા અને નમૂનાઓ જ્યાં સુધી તેઓ કાયદેસર સંશોધન માટે ઉપયોગી છે અને જરૂરી સુરક્ષા પગલાં છે ત્યાં સુધી, ડીપીડીપી એક્ટ અને અન્ય કાનૂની અથવા નિયમનકારી જવાબદારીઓ અનુસાર સંગ્રહિત કરી શકાય છે."},{"text":"જો તમે અભ્યાસથી સ્વતંત્ર વ્યક્તિ સાથે વાત કરવા અને સંમતિ પાછો ખેંચી લેવા માંગતા હો, તો તમે સંસ્થાકીય નીતિશાસ્ત્ર સમિતિ (IEC) નો સંપર્ક કરી શકો છો"},{"text":"નામઃ ડૉ. શ્રી વિદ્યા જગદીશ, આઇઇસી, તાનૂહના સચિવ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"સહભાગીઓની સંમતિ","declaration":"મેં સહભાગીતા માહિતી શીટ વાંચી અને સમજી છે અને આ અભ્યાસમાં સ્વૈચ્છિક રીતે ભાગ લેવાની પુષ્ટિ આપી છે. મને પ્રશ્નો પૂછવાની તક મળી છે, અને મારા બધા પ્રશ્નોના મારા સંતોષ માટે જવાબ આપવામાં આવ્યા છે. હું સમજી શકું છું કે મને મારી સંમતિ પાછો ખેંચવાનો અને કોઈપણ સમયે ભાગ લેવાનો ઇનકાર કરવાનો અધિકાર છે. હું આ અભ્યાસનો ભાગ બનવા માટે મારી સંમતિ આપું છું.","ageCheckboxLabel":"હું 18 વર્ષનો છું અથવા તેનાથી વધુ","voluntaryCheckboxLabel":"આ અભ્યાસ માટે જરૂરી માહિતી સ્વૈચ્છિક રીતે પૂરી પાડવામાં આવે છે"}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='gu';
UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"ಮಾಹಿತಿ ನೀಡಿದ ಒಪ್ಪಿಗೆ ರೂಪ","projectDetails":{"projectTitle":{"label":"ಯೋಜನೆಯ ಶೀರ್ಷಿಕೆ","value":"ಸ್ತನ ಕ್ಯಾನ್ಸರ್ ಅಪಾಯವನ್ನು ಊಹಿಸಲು AI ಶಕ್ತಗೊಂಡ ಸಾಧನ"},"iecReference":{"label":"ಐಇಸಿ ಉಲ್ಲೇಖ ಸಂಖ್ಯೆ","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"ಐಇಸಿ ಅನುಮೋದನೆ ದಿನಾಂಕ","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"ಐಇಸಿ ಅನುಮೋದನೆ ಅವಧಿ","value":"ಮಾರ್ಚ್ 2028ರ ವರೆಗೆ"}},"sections":[{"heading":"ಸ್ವಯಂಪ್ರೇರಿತ ಭಾಗವಹಿಸುವಿಕೆ","paragraphs":[{"text":"ಈ ಅಧ್ಯಯನದಲ್ಲಿ ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿದೆ. ನೀವು ಈ ಅಧ್ಯಯನದಲ್ಲಿ ಅಥವಾ ಈ ಅಧ್ಯಯನದ ಯಾವುದೇ ಭಾಗದಲ್ಲಿ ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಭಾಗವಹಿಸಲು ನಿರಾಕರಿಸಬಹುದು. ಅದೇ ರೀತಿ ಸಂಶೋಧಕನು ಯಾವುದೇ ಕಾರಣವನ್ನು ನೀಡದೆ ನಿಮ್ಮ ಪ್ರಯೋಗದಲ್ಲಿ ಭಾಗವಹಿಸುವಿಕೆಯನ್ನು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಕೊನೆಗೊಳಿಸುವ ಹಕ್ಕನ್ನು ಸಹ ಕಾಯ್ದಿರಿಸುತ್ತಾನೆ. ನಿಮ್ಮ ಭಾಗವಹಿಸುವಿಕೆಯನ್ನು ಹಿಂತೆಗೆದುಕೊಳ್ಳುವ ಅಥವಾ ಕೊನೆಗೊಳಿಸುವ ನಿರ್ಧಾರವು ನಿಮ್ಮ ಸಂಸ್ಥೆ / ವಿಶ್ವವಿದ್ಯಾಲಯ / ಆಸ್ಪತ್ರೆಯೊಂದಿಗಿನ ನಿಮ್ಮ ಸಂಬಂಧಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ ಅಥವಾ ನೀವು ಪಡೆಯುವ ಆರೈಕೆಯನ್ನು ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ. ಈ ಅಧ್ಯಯನದ ಸಮಯದಲ್ಲಿ ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಈ ಅಧ್ಯಯನದ ಬಗ್ಗೆ ಪ್ರಶ್ನೆಗಳನ್ನು ಕೇಳಲು ನಿಮ್ಮನ್ನು ಪ್ರೋತ್ಸಾಹಿಸಲಾಗುತ್ತದೆ."}]},{"heading":"ಈ ಅಧ್ಯಯನದ ಭಾಗವಾಗಿ ಸಂಗ್ರಹಿಸಿದ ಮಾಹಿತಿ","paragraphs":[{"text":"ಜನಸಂಖ್ಯಾಶಾಸ್ತ್ರ, ಜೀವನಶೈಲಿ, ಕುಟುಂಬದ ಇತಿಹಾಸ, ಋತುಚಕ್ರ ಮತ್ತು ಸಂತಾನೋತ್ಪತ್ತಿ ಆರೋಗ್ಯ ಮಾಹಿತಿ - ಅಗತ್ಯ"},{"text":"ವರದಿ ಜೊತೆಗೆ ಸ್ತನಗುಣಗಳು (ಅಗತ್ಯ)"},{"text":"ಅಲ್ಟ್ರಾಸೌಂಡ್ ಮತ್ತು/ಅಥವಾ ಬಯಾಪ್ಸಿ ವರದಿ (ಐಚ್ಛಿಕ)"}]},{"heading":"ಗೌಪ್ಯತೆ ಮತ್ತು ಡೇಟಾ ರಕ್ಷಣೆ","paragraphs":[{"text":"ಡೇಟಾ ಅನಾಮಧೇಯೀಕರಣಃ ಈ ಅಧ್ಯಯನದಲ್ಲಿ ಸಂಗ್ರಹಿಸಿದ ಎಲ್ಲಾ ಮಾಹಿತಿಯನ್ನು ನಿಮ್ಮ ಗೌಪ್ಯತೆಯನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು ಹಿಂತಿರುಗಿಸಲಾಗದ ಅನಾಮಧೇಯ ರೀತಿಯಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ, ಸಂಸ್ಕರಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ. ಸಂಗ್ರಹಿಸಿದ ಮಾಹಿತಿಯ ಸಂಗ್ರಹಣೆಯು ಡಿಜಿಟಲ್ ಪರ್ಸನಲ್ ಡೇಟಾ ಪ್ರೊಟೆಕ್ಷನ್ (ಡಿಪಿಡಿ) ಆಕ್ಟ್ ಮಾನದಂಡಗಳಿಗೆ ಅನುಗುಣವಾಗಿರುತ್ತದೆ."},{"text":"ಸಂಗ್ರಹಿಸಿದ ಡೇಟಾವನ್ನು ಭವಿಷ್ಯದ ಸಂಶೋಧನೆಯಲ್ಲಿ ಬಳಸಲಾಗುವುದು, ಇದರಲ್ಲಿ ಇತರ ಅಡಿಪಾಯ ಮಾದರಿಗಳ ಅಭಿವೃದ್ಧಿ ಸೇರಿದೆ."},{"text":"ಹಕ್ಕುಗಳುಃ ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಡೇಟಾವನ್ನು ಪ್ರವೇಶಿಸಲು ಮತ್ತು ಸರಿಪಡಿಸಲು ಮತ್ತು ಸಂಶೋಧನಾ ಪ್ರಕ್ರಿಯೆಗೆ ನಿಮ್ಮ ಒಪ್ಪಿಗೆಯನ್ನು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಹಿಂತೆಗೆದುಕೊಳ್ಳುವ ಹಕ್ಕು ನಿಮಗೆ ಇದೆ. ಹಿಂತೆಗೆದುಕೊಳ್ಳುವ ನಿರ್ಧಾರವು ನೀವು ಪಡೆಯುವ ನಿಯಮಿತ ವೈದ್ಯಕೀಯ ಆರೈಕೆಯನ್ನು ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ."},{"text":"ಸಂರಕ್ಷಣೆಃ ನಿಮ್ಮ ಅನಧಿಕೃತವಾಗಿ ಅನಾಮಧೇಯಗೊಳಿಸಿದ ಡೇಟಾ ಮತ್ತು ಮಾದರಿಗಳನ್ನು ಕಾನೂನುಬದ್ಧ ಸಂಶೋಧನೆಗೆ ಉಪಯುಕ್ತವಾಗಿದ್ದರೆ ಮತ್ತು ಡಿಪಿಡಿಪಿ ಕಾಯ್ದೆ ಮತ್ತು ಇತರ ಕಾನೂನು ಅಥವಾ ನಿಯಂತ್ರಕ ಕಟ್ಟುಪಾಡುಗಳಿಗೆ ಅನುಗುಣವಾಗಿ ಅಗತ್ಯವಾದ ರಕ್ಷಣೆ ಇದ್ದಲ್ಲಿ ಸಂಗ್ರಹಿಸಬಹುದು."},{"text":"ನೀವು ಅಧ್ಯಯನದ ಬಗ್ಗೆ ಸ್ವತಂತ್ರವಾಗಿರುವ ಯಾರೊಂದಿಗೂ ಮಾತನಾಡಲು ಬಯಸಿದರೆ ಮತ್ತು ಒಪ್ಪಿಗೆಯನ್ನು ಹಿಂತೆಗೆದುಕೊಳ್ಳಲು ಬಯಸಿದರೆ, ನೀವು ಇನ್ಸ್ಟಿಟ್ಯೂಷನಲ್ ಎಥಿಕ್ಸ್ ಕಮಿಟಿಯನ್ನು (ಐಇಸಿ) ಸಂಪರ್ಕಿಸಬಹುದು"},{"text":"ಹೆಸರುಃ ಡಾ. ಶ್ರೀ ವಿದ್ಯಾ ಜಗಡಿಶ್, ಐಇಸಿ ಕಾರ್ಯದರ್ಶಿ, ಟ್ಯಾನುಹ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"ಭಾಗವಹಿಸುವವರ ಒಪ್ಪಿಗೆ","declaration":"ನಾನು ಭಾಗವಹಿಸುವಿಕೆಯ ಮಾಹಿತಿ ಫಲಕವನ್ನು ಓದಿದ್ದೇನೆ ಮತ್ತು ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೇನೆ ಮತ್ತು ಈ ಅಧ್ಯಯನದಲ್ಲಿ ಸ್ವಯಂಪ್ರೇರಣೆಯಿಂದ ಭಾಗವಹಿಸಲು ದೃಢಪಡಿಸಿದ್ದೇನೆ. ನನಗೆ ಪ್ರಶ್ನೆಗಳನ್ನು ಕೇಳುವ ಅವಕಾಶ ಸಿಕ್ಕಿದೆ ಮತ್ತು ನನ್ನ ಎಲ್ಲ ಪ್ರಶ್ನೆಗಳಿಗೆ ತೃಪ್ತಿಗಾಗಿ ಉತ್ತರಿಸಲಾಗಿದೆ. ನನ್ನ ಒಪ್ಪಿಗೆಯನ್ನು ಹಿಂತೆಗೆದುಕೊಳ್ಳುವ ಮತ್ತು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಭಾಗವಹಿಸಲು ನಿರಾಕರಿಸುವ ಹಕ್ಕನ್ನು ನಾನು ಹೊಂದಿದ್ದೇನೆ. ಈ ಅಧ್ಯಯನದಲ್ಲಿ ಭಾಗವಹಿಸಲು ನನ್ನ ಒಪ್ಪಿಗೆಯನ್ನು ನಾನು ನೀಡುತ್ತೇನೆ.","ageCheckboxLabel":"ನಾನು 18 ವರ್ಷ ಅಥವಾ ಅದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ವಯಸ್ಸಿನವನು","voluntaryCheckboxLabel":"ಈ ಅಧ್ಯಯನಕ್ಕೆ ಬೇಕಾದ ಮಾಹಿತಿಯನ್ನು ಸ್ವಯಂಪ್ರೇರಣೆಯಿಂದ ಒದಗಿಸಲಾಗುತ್ತಿದೆ."}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='kn';
UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"വിവരമുള്ള സമ്മത ഫോം","projectDetails":{"projectTitle":{"label":"പദ്ധതിയുടെ പേര്","value":"സ്തനാർബുദം പ്രവചിക്കാനുള്ള ഉപകരണം"},"iecReference":{"label":"ഐ. ഇ. സി. റഫറൻസ് നമ്പർ","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"ഐ. ഇ. സി അംഗീകാര തീയതി","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"ഐ. ഇ. സി. അംഗീകാര കാലാവധി","value":"2028 മാർച്ചില് വരെ"}},"sections":[{"heading":"സ്വമേധയാ പങ്കെടുക്കുക","paragraphs":[{"text":"ഈ പഠനത്തിലെ നിങ്ങളുടെ പങ്കാളിത്തം സ്വമേധയാ ആണ്. ഈ പഠനത്തിൽ അല്ലെങ്കിൽ ഈ പഠനത്തിന്റെ ഏതെങ്കിലും ഭാഗത്ത് എപ്പോൾ വേണമെങ്കിലും പങ്കെടുക്കാൻ നിങ്ങൾ വിസമ്മതിക്കും. അതുപോലെ തന്നെ, ഒരു കാരണവും നൽകാതെ എപ്പോൾ വേണമെങ്കിലും പരീക്ഷണത്തിൽ പങ്കെടുക്കുന്നതിനെ അവസാനിപ്പിക്കാനുള്ള അവകാശവും അന്വേഷകന് നിക്ഷിപ്തമാണ്. നിങ്ങളുടെ പങ്കാളിത്തം പിൻവലിക്കുന്നതിനോ അവസാനിപ്പിക്കുന്നതിനോ ഉള്ള തീരുമാനം നിങ്ങളുടെ ഇൻസ്റ്റിറ്റ്യൂട്ട് / യൂണിവേഴ്സിറ്റി / ആശുപത്രി എന്നിവയുമായുള്ള ബന്ധത്തെ ബാധിക്കുകയില്ല. അല്ലെങ്കിൽ നിങ്ങൾക്ക് ലഭിക്കുന്ന പരിചരണത്തെ ബാധിക്കുകയില്ല. പഠന സമയത്ത് ഏത് സമയത്തും ഈ പഠനത്തെക്കുറിച്ച് ചോദ്യങ്ങൾ ചോദിക്കാൻ നിങ്ങളെ പ്രോത്സാഹിപ്പിക്കുന്നു."}]},{"heading":"ഈ പഠനത്തിന്റെ ഭാഗമായി ശേഖരിച്ച വിവരങ്ങൾ","paragraphs":[{"text":"ജനസംഖ്യാശാസ്ത്രവും ജീവിതശൈലിയും കുടുംബ ചരിത്രവും ആർത്തവവും പ്രത്യുത്പാദനവും സംബന്ധിച്ച വിവരങ്ങളും - ആവശ്യമായത്"},{"text":"മാംമോഗ്രാമുകളും റിപ്പോർട്ടും (ആവശ്യമാണ്)"},{"text":"അൾട്രാസൌണ്ട്,/അല്ലെങ്കിൽ ബയോപ്സി റിപ്പോർട്ട് (ഓപ്ഷണൽ)"}]},{"heading":"രഹസ്യാത്മകതയും ഡാറ്റാ പരിരക്ഷയും","paragraphs":[{"text":"ഡാറ്റ അജ്ഞാതമാക്കൽഃ ഈ പഠനത്തിൽ ശേഖരിച്ച എല്ലാ വിവരങ്ങളും നിങ്ങളുടെ സ്വകാര്യത ഉറപ്പാക്കുന്നതിന് തിരിവറ്റാനാവാത്ത വിധത്തിൽ അജ്ഞാതമാക്കിയ രീതിയിൽ ശേഖരിക്കുകയും പ്രോസസ്സ് ചെയ്യുകയും സംഭരിക്കുകയും ചെയ്യും. ശേഖരിച്ച വിവരങ്ങളുടെ സംഭരണം ഡിജിറ്റൽ വ്യക്തിഗത ഡാറ്റാ പരിരക്ഷണ നിയമം (ഡിപിഡിപി) മാനദണ്ഡങ്ങൾ പാലിക്കുന്നു."},{"text":"ശേഖരിച്ച ഡാറ്റ ഭാവിയിലെ ഗവേഷണത്തില് ഉപയോഗിക്കും, മറ്റു അടിസ്ഥാന മാതൃകകളുടെ വികസനവും ഉൾപ്പെടെ."},{"text":"അവകാശങ്ങൾഃ നിങ്ങളുടെ വ്യക്തിഗത ഡാറ്റ ആക്സസ് ചെയ്യാനും തിരുത്താനും ഗവേഷണ പ്രോസസ്സിംഗിന് വേണ്ടിയുള്ള സമ്മതം എപ്പോൾ വേണമെങ്കിലും പിൻവലിക്കാനും നിങ്ങൾക്ക് അവകാശമുണ്ട്. പിൻവലിക്കാനുള്ള തീരുമാനം നിങ്ങൾക്ക് ലഭിക്കുന്ന പതിവ് ക്ലിനിക്കൽ പരിചരണത്തെ ബാധിക്കുകയില്ല."},{"text":"സൂക്ഷിക്കൽഃ നിങ്ങളുടെ അജ്ഞാതമാക്കിയ ഡാറ്റയും സാമ്പിളുകളും നിയമപരമായി ഗവേഷണം നടത്താൻ ഉപയോഗപ്രദവും ആവശ്യമായ സംരക്ഷണങ്ങളും ഉള്ളിടത്തോളം കാലം സൂക്ഷിക്കാം."},{"text":"പഠനത്തില് നിന്ന് സ്വതന്ത്രമായ ഒരാളുമായി സംസാരിക്കാനും സമ്മതം പിൻവലിക്കാനും നിങ്ങൾ ആഗ്രഹിക്കുന്നുവെങ്കില്, നിങ്ങള് ക്ക് സ്ഥാപനപരമായ ധാർമിക സമിതിയോട് (IEC) ബന്ധപ്പെടാം."},{"text":"പേര്ഃ ഡോ. ശ്രീ വിദ്യ ജഗാദിഷ്, ഐ. ഇ. സി സെക്രട്ടറി, താനു"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"പങ്കാളികളുടെ സമ്മതം","declaration":"പങ്കാളിത്ത വിവരപത്രിക വായിക്കുകയും മനസ്സിലാക്കുകയും ചെയ്തു. ഈ പഠനത്തില് സ്വമേധയാ പങ്കെടുക്കുന്നതായി ഞാന് സ്ഥിരീകരിച്ചു. എനിക്ക് ചോദ്യങ്ങള് ചോദിക്കാനുള്ള അവസരം ലഭിച്ചു. എന്റെ എല്ലാ ചോദ്യങ്ങള് ക്കും തൃപ്തികരമായി ഉത്തരം നല് കപ്പെട്ടു. എന്റെ സമ്മതം പിൻവലിക്കാനും എപ്പോൾ വേണമെങ്കിലും പങ്കെടുക്കാന് വിസമ്മതിക്കാനും എനിക്ക് അവകാശമുണ്ടെന്ന് ഞാന് മനസ്സിലാക്കുന്നു. ഈ പഠനത്തില് പങ്കെടുക്കാന് ഞാന് സമ്മതം നല് കുന്നു.","ageCheckboxLabel":"എനിക്ക് 18 വയസ്സോ അതിൽ കൂടുതലോ പ്രായമുണ്ട്","voluntaryCheckboxLabel":"ഈ പഠനത്തിന് ആവശ്യമായ വിവരങ്ങൾ സ്വമേധയാ നല് കുന്നു."}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='ml';
UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"माहितीपूर्ण संमतीचा फॉर्म","projectDetails":{"projectTitle":{"label":"प्रकल्पाचे शीर्षक","value":"एआयने स्तन कर्करोगाचा धोका अंदाज लावण्याची साधने"},"iecReference":{"label":"आयईसी संदर्भ क्रमांक","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"आयईसी मंजुरीची तारीख","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"आयईसी मंजुरी कालावधी","value":"मार्च 2028 पर्यंत"}},"sections":[{"heading":"स्वेच्छेने सहभाग","paragraphs":[{"text":"या अभ्यासामध्ये तुमचे सहभाग स्वेच्छेने आहे. तुम्ही या अभ्यासामध्ये किंवा या अभ्यासाच्या कोणत्याही भागात कोणत्याही वेळी सहभागी होण्यास नकार देऊ शकता. त्याचप्रमाणे संशोधक कोणत्याही वेळी कारण न दिल्याशिवाय प्रयोगात तुमचे सहभाग थांबवण्याचा अधिकार राखतो. आपले सहभाग मागे घेण्याचा किंवा समाप्त करण्याचा निर्णय आपल्या संस्थेशी / विद्यापीठ / रुग्णालयात असलेल्या संबंधांवर किंवा आपल्याला प्राप्त झालेल्या काळजीवर परिणाम करणार नाही. आपण या अभ्यासाबद्दल कोणत्याही वेळी प्रश्न विचारण्यास प्रोत्साहित केले जाते."}]},{"heading":"या अभ्यासाच्या भाग म्हणून गोळा केलेली माहिती","paragraphs":[{"text":"जनसांख्यिकीय, जीवनशैली, कौटुंबिक इतिहास, मासिक पाळी आणि प्रजनन आरोग्य माहिती - आवश्यक"},{"text":"मॅमोग्राम आणि अहवाल (आवश्यक)"},{"text":"अल्ट्रासाऊंड आणि/किंवा बायोप्सी अहवाल (पर्यायी)"}]},{"heading":"गोपनीयता आणि डेटा संरक्षण","paragraphs":[{"text":"डेटा अनामिकीकरणः या अभ्यासात गोळा केलेली सर्व माहिती आपल्या गोपनीयतेची खात्री करण्यासाठी अपरिवर्तनीयपणे अनामिक पद्धतीने गोळा केली जाईल, प्रक्रिया केली जाईल आणि संग्रहित केली जाईल. गोळा केलेली माहिती संचयित करणे डिजिटल वैयक्तिक डेटा संरक्षण कायद्याचे (डीपीडीपी) मानके पाळते."},{"text":"या माहितीचा वापर भविष्यातील संशोधनात केला जाईल, ज्यात इतर पायाभूत मॉडेलचा समावेश आहे."},{"text":"अधिकारः तुम्हाला तुमच्या वैयक्तिक डेटामध्ये प्रवेश करण्याचा आणि सुधारण्याचा आणि संशोधन प्रक्रियेसाठी तुमची संमती कोणत्याही वेळी मागे घेण्याचा अधिकार आहे."},{"text":"आरक्षणासाठी: डीपीडीपी कायदा आणि इतर कायदेशीर किंवा नियामक जबाबदाऱ्यांनुसार, आपल्या अपरिवर्तनीयपणे अनामिक केलेली माहिती आणि नमुने जोपर्यंत ते कायदेशीर संशोधनासाठी उपयुक्त आहेत आणि आवश्यक सुरक्षा उपाययोजना आहेत तोपर्यंत संग्रहित केली जाऊ शकतात."},{"text":"जर तुम्हाला अभ्यासातून स्वतंत्र असलेल्या व्यक्तीशी बोलण्याची इच्छा असेल आणि तुम्ही संमती मागे घेऊ इच्छित असाल तर तुम्ही संस्थागत नैतिकता समितीशी संपर्क साधू शकता."},{"text":"नाव: डॉ. श्री विद्या जगदीश, आयईसीचे सचिव, तनुह"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"सहभागी संमती","declaration":"मी सहभाग माहितीपत्रिका वाचली आणि समजली आहे आणि या अभ्यासात स्वेच्छेने सहभागी होण्याची पुष्टी केली आहे. मला प्रश्न विचारण्याची संधी मिळाली आहे आणि माझ्या सर्व प्रश्नांची उत्तरे माझ्या समाधानाने दिली गेली आहेत. मला समजले आहे की मला कोणत्याही वेळी माझी संमती मागे घेण्याचा आणि सहभागी होण्यास नकार देण्याचा अधिकार आहे. मी या अभ्यासात सहभागी होण्यास माझी संमती देतो.","ageCheckboxLabel":"मी १८ वर्षांचा किंवा त्याहून अधिक आहे","voluntaryCheckboxLabel":"या अभ्यासासाठी आवश्यक माहिती स्वेच्छेने उपलब्ध करून दिली जात आहे."}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='mr';
UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"ସୂଚନାପ୍ରାପ୍ତ ସମ୍ମତି ଫର୍ମ","projectDetails":{"projectTitle":{"label":"ପ୍ରକଳ୍ପର ନାମ","value":"ଏଆଇ ଦ୍ୱାରା ସ୍ତନ କର୍କଟ ଆଶଙ୍କା ଆକଳନ କରିବାର ସାଧନ"},"iecReference":{"label":"ଆଇଇସି ରେଫରେନ୍ସ ନମ୍ବର","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"ଆଇଇସି ଅନୁମୋଦନ ତାରିଖ","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"ଆଇଇସି ଅନୁମୋଦନ ଅବଧି","value":"2028 ମାର୍ଚ୍ଚ ପର୍ଯ୍ୟନ୍ତ"}},"sections":[{"heading":"ସ୍ୱେଚ୍ଛାକୃତ ଅଂଶଗ୍ରହଣ","paragraphs":[{"text":"ଏହି ଅଧ୍ୟୟନରେ ଆପଣଙ୍କର ଅଂଶଗ୍ରହଣ ସ୍ୱେଚ୍ଛାକୃତ ଅଟେ । ଆପଣ ଏହି ଅଧ୍ୟୟନରେ କିମ୍ବା ଏହି ଅଧ୍ୟୟନର ଯେକୌଣସି ଅଂଶରେ ଯେକୌଣସି ସମୟରେ ଅଂଶଗ୍ରହଣ କରିବାକୁ ମନା କରିପାରିବେ । ସେହିପରି ଅନୁସନ୍ଧାନକାରୀ ମଧ୍ୟ କୌଣସି କାରଣ ନଦେଇ ଯେକୌଣସି ସମୟରେ ପରୀକ୍ଷାରେ ଆପଣଙ୍କର ଅଂଶଗ୍ରହଣ ସମାପ୍ତ କରିବାର ଅଧିକାର ସଂରକ୍ଷିତ ରଖିଛନ୍ତି । ଆପଣଙ୍କ ଅଂଶଗ୍ରହଣକୁ ପ୍ରତ୍ୟାହାର କରିବା କିମ୍ବା ସମାପ୍ତ କରିବାର ନିଷ୍ପତ୍ତି ଆପଣଙ୍କ ପ୍ରତିଷ୍ଠାନ / ବିଶ୍ୱବିଦ୍ୟାଳୟ / ଡାକ୍ତରଖାନା ସହିତ ଆପଣଙ୍କ ସମ୍ପର୍କକୁ ପ୍ରଭାବିତ କରିବ ନାହିଁ କିମ୍ବା ଆପଣ ପାଉଥିବା ଯତ୍ନ ଉପରେ ପ୍ରଭାବ ପକାଇବ ନାହିଁ । ଆପଣ ଏହି ଅଧ୍ୟୟନ ବିଷୟରେ ଯେକୌଣସି ସମୟରେ ପ୍ରଶ୍ନ ପଚାରିବାକୁ ଉତ୍ସାହିତ କରାଗଲା ।"}]},{"heading":"ଏହି ଅଧ୍ୟୟନର ଅଂଶବିଶେଷ ଭାବେ ସଂଗ୍ରହ କରାଯାଇଥିବା ସୂଚନା","paragraphs":[{"text":"ଜନସଂଖ୍ୟା, ଜୀବନଶୈଳୀ, ପାରିବାରିକ ଇତିହାସ, ମାସିକ ଓ ପ୍ରଜନନ ସ୍ୱାସ୍ଥ୍ୟ ସୂଚନା - ଆବଶ୍ୟକ"},{"text":"ରିପୋର୍ଟ ସହିତ ମ୍ୟାମୋଗ୍ରାମ୍ (ଅବଶ୍ୟକ)"},{"text":"ଅଲଟ୍ରାସାଉଣ୍ଡ ଏବଂ/କିମ୍ବା ବାୟୋପସି ରିପୋର୍ଟ (ଅବଶ୍ୟକ)"}]},{"heading":"ଗୋପନୀୟତା ଏବଂ ତଥ୍ୟ ସୁରକ୍ଷା","paragraphs":[{"text":"ଡାଟା ଅନାନୋମିଜେସନ୍: ଏହି ଅଧ୍ୟୟନରେ ସଂଗୃହୀତ ସମସ୍ତ ସୂଚନା ଆପଣଙ୍କ ଗୋପନୀୟତା ସୁନିଶ୍ଚିତ କରିବା ପାଇଁ ଏକ ଅପରିବର୍ତ୍ତନୀୟ ଭାବରେ ଅନାନୋମିଜେଡ୍ ଉପାୟରେ ସଂଗ୍ରହ, ପ୍ରକ୍ରିୟାକରଣ ଏବଂ ସଂରକ୍ଷଣ କରାଯିବ। ସଂଗୃହୀତ ସୂଚନା ସଂରକ୍ଷଣ ଡିଜିଟାଲ୍ ବ୍ୟକ୍ତିଗତ ତଥ୍ୟ ସୁରକ୍ଷା (ଡିପିଡି) ଆଇନ ମାନକକୁ ଅନୁସରଣ କରେ।"},{"text":"ଏହି ତଥ୍ୟକୁ ଭବିଷ୍ୟତରେ ଗବେଷଣା ପାଇଁ ବ୍ୟବହାର କରାଯିବ, ଯେଉଁଥିରେ ଅନ୍ୟ ଫାଉଣ୍ଡେସନ ମଡେଲର ବିକାଶ ମଧ୍ୟ ସାମିଲ ହେବ ।"},{"text":"ଅଧିକାର: ଆପଣଙ୍କର ବ୍ୟକ୍ତିଗତ ତଥ୍ୟକୁ ଯେକୌଣସି ସମୟରେ ପ୍ରବେଶ କରିବାର ଏବଂ ସଂଶୋଧନ କରିବାର ଅଧିକାର ଅଛି ଏବଂ ଗବେଷଣା ପ୍ରକ୍ରିୟାକରଣ ପାଇଁ ଆପଣଙ୍କ ସମ୍ମତି ପ୍ରତ୍ୟାହାର କରିବାର ଅଧିକାର ଅଛି । ପ୍ରତ୍ୟାହାର ନିଷ୍ପତ୍ତି ଆପଣଙ୍କ ନିୟମିତ କ୍ଲିନିକାଲ୍ ଚିକିତ୍ସା ଉପରେ ପ୍ରଭାବ ପକାଇବ ନାହିଁ ।"},{"text":"ସଂରକ୍ଷଣ: ଆପଣଙ୍କ ଅନିବର୍ତ୍ତନୀୟ ଭାବେ ଅଜ୍ଞାତ ତଥ୍ୟ ଏବଂ ନମୁନାଗୁଡିକ ଯେ ପର୍ଯ୍ୟନ୍ତ ଆଇନଗତ ଅନୁସନ୍ଧାନ ପାଇଁ ଉପଯୋଗୀ ଏବଂ ଆବଶ୍ୟକୀୟ ସୁରକ୍ଷା ବ୍ୟବସ୍ଥା ରହିଛି, ସେପର୍ଯ୍ୟନ୍ତ ଡିପିଡିଏଫ ଆଇନ ଏବଂ ଅନ୍ୟାନ୍ୟ ଆଇନଗତ କିମ୍ବା ନିୟାମକ କର୍ତ୍ତବ୍ୟ ଅନୁଯାୟୀ ସଂରକ୍ଷଣ କରାଯାଇପାରିବ ।"},{"text":"ଯଦି ଆପଣ କୌଣସି ବ୍ୟକ୍ତିଙ୍କ ସହିତ ଆଲୋଚନା କରିବାକୁ ଚାହୁଁଛନ୍ତି ଏବଂ ଏହି ଅଧ୍ୟୟନରୁ ଆପଣଙ୍କ ସମ୍ମତି ପ୍ରତ୍ୟାହାର କରିବାକୁ ଚାହୁଁଛନ୍ତି, ତେବେ ଆପଣ ସଂସ୍ଥାଗତ ନୈତିକତା କମିଟି (ଆଇଇସି) କୁ ଯୋଗାଯୋଗ କରିପାରିବେ ।"},{"text":"ନାମ: ଡଃ ଶ୍ରୀ ବିଦ୍ୟା ଜଗଦୀଶ, ଆଇଇସି ସଚିବ, ତନୁ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"ଅଂଶଗ୍ରହଣକାରୀଙ୍କ ସମ୍ମତି","declaration":"ମୁଁ ଏହି ଅଧ୍ୟୟନରେ ସ୍ୱେଚ୍ଛାକୃତ ଭାବେ ଅଂଶଗ୍ରହଣ କରିବା ପାଇଁ ସକ୍ଷମ ହୋଇଛି ଏବଂ ମୁଁ ଏହି ଅଂଶଗ୍ରହଣ ସୂଚକାଙ୍କକୁ ପଢ଼ିଛି ଏବଂ ବୁଝିଛି । ମୋର ପ୍ରଶ୍ନ ପଚାରିବାର ସୁଯୋଗ ଅଛି ଏବଂ ମୋର ସମସ୍ତ ପ୍ରଶ୍ନର ଉତ୍ତର ମୋତେ ସନ୍ତୋଷଜନକ ଭାବରେ ମିଳିଛି । ମୁଁ ବୁଝିଛି ଯେ ମୋର ସମ୍ମତିକୁ ଯେକୌଣସି ସମୟରେ ପ୍ରତ୍ୟାହାର କରିବାର ଅଧିକାର ଅଛି ଏବଂ ମୁଁ ଏଥିରେ ଅଂଶଗ୍ରହଣ କରିବାକୁ ମନା କରୁଛି । ମୁଁ ଏହି ଅଧ୍ୟୟନରେ ଅଂଶଗ୍ରହଣ କରିବାକୁ ମୋର ସମ୍ମତି ଦେଉଛି ।","ageCheckboxLabel":"ମୋର ବୟସ ୧୮ ବର୍ଷ କିମ୍ବା ତା''ଠାରୁ ଅଧିକ","voluntaryCheckboxLabel":"ଏହି ଅଧ୍ୟୟନରେ ଆବଶ୍ୟକୀୟ ସୂଚନା ସ୍ୱେଚ୍ଛାକୃତ ଭାବେ ପ୍ରଦାନ କରାଯାଉଛି ।"}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='or';
UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"ਸੂਚਿਤ ਸਹਿਮਤੀ ਫਾਰਮ","projectDetails":{"projectTitle":{"label":"ਪ੍ਰੋਜੈਕਟ ਦਾ ਸਿਰਲੇਖ","value":"ਆਈ. ਏ. ਸਮਰੱਥ ਛਾਤੀ ਦੇ ਕੈਂਸਰ ਦੇ ਜੋਖਮ ਦੀ ਭਵਿੱਖਬਾਣੀ ਕਰਨ ਵਾਲੀ ਟੂਲ"},"iecReference":{"label":"ਆਈਈਸੀ ਹਵਾਲਾ ਨੰਬਰ","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"ਆਈਈਸੀ ਪ੍ਰਵਾਨਗੀ ਦੀ ਮਿਤੀ","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"ਆਈਈਸੀ ਪ੍ਰਵਾਨਗੀ ਦੀ ਮਿਆਦ","value":"ਮਾਰਚ 2028 ਤੱਕ"}},"sections":[{"heading":"ਖ਼ੁਦਮੁਖ਼ਤਿਆਰ ਭਾਗੀਦਾਰੀ","paragraphs":[{"text":"ਇਸ ਅਧਿਐਨ ਵਿੱਚ ਤੁਹਾਡੀ ਭਾਗੀਦਾਰੀ ਸਵੈਇੱਛੁਕ ਹੈ। ਤੁਸੀਂ ਇਸ ਅਧਿਐਨ ਵਿੱਚ ਜਾਂ ਇਸ ਅਧਿਐਨ ਦੇ ਕਿਸੇ ਵੀ ਹਿੱਸੇ ਵਿੱਚ ਕਿਸੇ ਵੀ ਸਮੇਂ ਹਿੱਸਾ ਲੈਣ ਤੋਂ ਇਨਕਾਰ ਕਰ ਸਕਦੇ ਹੋ। ਇਸੇ ਤਰ੍ਹਾਂ ਖੋਜਕਰਤਾ ਨੂੰ ਵੀ ਕਿਸੇ ਵੀ ਸਮੇਂ ਬਿਨਾਂ ਕਾਰਨ ਦੇ ਪ੍ਰਯੋਗ ਵਿੱਚ ਤੁਹਾਡੀ ਭਾਗੀਦਾਰੀ ਨੂੰ ਖਤਮ ਕਰਨ ਦਾ ਅਧਿਕਾਰ ਰੱਖਿਆ ਜਾਂਦਾ ਹੈ। ਤੁਹਾਡੀ ਭਾਗੀਦਾਰੀ ਨੂੰ ਵਾਪਸ ਲੈਣ ਜਾਂ ਖਤਮ ਕਰਨ ਦਾ ਫੈਸਲਾ ਤੁਹਾਡੇ ਇੰਸਟੀਚਿਊਟ / ਯੂਨੀਵਰਸਿਟੀ / ਹਸਪਤਾਲ ਨਾਲ ਤੁਹਾਡੇ ਸੰਬੰਧਾਂ ਨੂੰ ਪ੍ਰਭਾਵਤ ਨਹੀਂ ਕਰੇਗਾ ਜਾਂ ਤੁਹਾਡੀ ਦੇਖਭਾਲ ਨੂੰ ਪ੍ਰਭਾਵਤ ਨਹੀਂ ਕਰੇਗਾ. ਤੁਹਾਨੂੰ ਅਧਿਐਨ ਦੌਰਾਨ ਕਿਸੇ ਵੀ ਸਮੇਂ ਇਸ ਅਧਿਐਨ ਬਾਰੇ ਪ੍ਰਸ਼ਨ ਪੁੱਛਣ ਲਈ ਉਤਸ਼ਾਹਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।"}]},{"heading":"ਇਸ ਅਧਿਐਨ ਦੇ ਹਿੱਸੇ ਵਜੋਂ ਇਕੱਠੀ ਕੀਤੀ ਗਈ ਜਾਣਕਾਰੀ","paragraphs":[{"text":"ਜਨਸੰਖਿਆ, ਜੀਵਨ ਸ਼ੈਲੀ, ਪਰਿਵਾਰਕ ਇਤਿਹਾਸ, ਮਹੀਨਾਵਾਰ ਅਤੇ ਪ੍ਰਜਨਨ ਸਿਹਤ ਜਾਣਕਾਰੀ - ਜ਼ਰੂਰੀ"},{"text":"ਰਿਪੋਰਟ ਦੇ ਨਾਲ ਮੈਮੋਗ੍ਰਾਮ (ਜ਼ਰੂਰੀ)"},{"text":"ਅਲਟਰਾਸਾਊਂਡ ਅਤੇ/ਜਾਂ ਬਾਇਓਪਸੀ ਰਿਪੋਰਟ (ਵਿਕਲਪਿਕ)"}]},{"heading":"ਗੁਪਤਤਾ ਅਤੇ ਡਾਟਾ ਸੁਰੱਖਿਆ","paragraphs":[{"text":"ਡਾਟਾ ਅਗਿਆਤਕਰਨਃ ਇਸ ਅਧਿਐਨ ਵਿੱਚ ਇਕੱਠੀ ਕੀਤੀ ਸਾਰੀ ਜਾਣਕਾਰੀ ਤੁਹਾਡੀ ਗੋਪਨੀਯਤਾ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਣ ਲਈ ਇੱਕ ਅਟੁੱਟ ਅਗਿਆਤ ਤਰੀਕੇ ਨਾਲ ਇਕੱਠੀ ਕੀਤੀ ਜਾਏਗੀ, ਪ੍ਰਕਿਰਿਆ ਕੀਤੀ ਜਾਏਗੀ ਅਤੇ ਸਟੋਰ ਕੀਤੀ ਜਾਏਗੀ. ਇਕੱਠੀ ਕੀਤੀ ਜਾਣਕਾਰੀ ਸਟੋਰੇਜ ਡਿਜੀਟਲ ਨਿੱਜੀ ਡਾਟਾ ਪ੍ਰੋਟੈਕਸ਼ਨ (ਡੀਪੀਡੀਪੀ) ਐਕਟ ਦੇ ਮਾਪਦੰਡਾਂ ਦੀ ਪਾਲਣਾ ਕਰਦੀ ਹੈ."},{"text":"ਇਕੱਠੇ ਕੀਤੇ ਗਏ ਡੇਟਾ ਦਾ ਭਵਿੱਖ ਵਿੱਚ ਖੋਜ ਵਿੱਚ ਇਸਤੇਮਾਲ ਕੀਤਾ ਜਾਵੇਗਾ, ਜਿਸ ਵਿੱਚ ਹੋਰ ਫਾਊਂਡੇਸ਼ਨ ਮਾਡਲਾਂ ਦਾ ਵਿਕਾਸ ਵੀ ਸ਼ਾਮਲ ਹੈ।"},{"text":"ਅਧਿਕਾਰਃ ਤੁਹਾਡੇ ਕੋਲ ਆਪਣੇ ਨਿੱਜੀ ਡੇਟਾ ਤੱਕ ਪਹੁੰਚ ਅਤੇ ਸੁਧਾਰ ਕਰਨ ਅਤੇ ਖੋਜ ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਆਪਣੀ ਸਹਿਮਤੀ ਕਿਸੇ ਵੀ ਸਮੇਂ ਵਾਪਸ ਲੈਣ ਦਾ ਅਧਿਕਾਰ ਹੈ। ਵਾਪਸ ਲੈਣ ਦਾ ਫੈਸਲਾ ਤੁਹਾਨੂੰ ਪ੍ਰਾਪਤ ਨਿਯਮਤ ਕਲੀਨਿਕਲ ਦੇਖਭਾਲ ਨੂੰ ਪ੍ਰਭਾਵਤ ਨਹੀਂ ਕਰੇਗਾ।"},{"text":"ਸਟੋਰਃ ਤੁਹਾਡੇ ਅਣਜਾਣ ਕੀਤੇ ਡੇਟਾ ਅਤੇ ਨਮੂਨੇ ਉਦੋਂ ਤੱਕ ਸਟੋਰ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ ਜਦੋਂ ਤੱਕ ਉਹ ਕਾਨੂੰਨੀ ਖੋਜ ਲਈ ਲਾਭਦਾਇਕ ਹਨ ਅਤੇ ਲੋੜੀਂਦੇ ਸੁਰੱਖਿਆ ਉਪਾਅ ਲਾਗੂ ਹਨ, ਡੀਪੀਡੀਪੀ ਐਕਟ ਅਤੇ ਹੋਰ ਕਾਨੂੰਨੀ ਜਾਂ ਨਿਯਮਿਤ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਦੇ ਅਨੁਸਾਰ."},{"text":"ਜੇਕਰ ਤੁਸੀਂ ਅਧਿਐਨ ਤੋਂ ਸੁਤੰਤਰ ਵਿਅਕਤੀ ਨਾਲ ਗੱਲ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ ਅਤੇ ਸਹਿਮਤੀ ਵਾਪਸ ਲੈਣਾ ਚਾਹੁੰਦੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਸੰਸਥਾਗਤ ਨੈਤਿਕਤਾ ਕਮੇਟੀ (ਆਈਈਸੀ) ਨਾਲ ਸੰਪਰਕ ਕਰ ਸਕਦੇ ਹੋ"},{"text":"ਨਾਮਃ ਡਾ. ਸ਼੍ਰੀ ਵਿਦਿਆ ਜਗਾਡੀਸ਼, ਆਈਈਸੀ, ਟੈਨੂਹ ਦੇ ਸਕੱਤਰ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"ਭਾਗੀਦਾਰ ਸਹਿਮਤੀ","declaration":"ਮੈਂ ਭਾਗੀਦਾਰੀ ਜਾਣਕਾਰੀ ਸ਼ੀਟ ਪੜ੍ਹੀ ਅਤੇ ਸਮਝੀ ਹੈ ਅਤੇ ਇਸ ਅਧਿਐਨ ਵਿੱਚ ਸਵੈਇੱਛੁਕ ਤੌਰ ''ਤੇ ਹਿੱਸਾ ਲੈਣ ਦੀ ਪੁਸ਼ਟੀ ਕੀਤੀ ਹੈ। ਮੈਨੂੰ ਸਵਾਲ ਪੁੱਛਣ ਦਾ ਮੌਕਾ ਮਿਲਿਆ ਹੈ ਅਤੇ ਮੇਰੇ ਸਾਰੇ ਸਵਾਲਾਂ ਦੇ ਮੇਰੇ ਸੰਤੁਸ਼ਟੀ ਲਈ ਜਵਾਬ ਦਿੱਤੇ ਗਏ ਹਨ। ਮੈਂ ਸਮਝਦਾ ਹਾਂ ਕਿ ਮੈਨੂੰ ਆਪਣੀ ਸਹਿਮਤੀ ਵਾਪਸ ਲੈਣ ਅਤੇ ਕਿਸੇ ਵੀ ਸਮੇਂ ਹਿੱਸਾ ਲੈਣ ਤੋਂ ਇਨਕਾਰ ਕਰਨ ਦਾ ਅਧਿਕਾਰ ਹੈ। ਮੈਂ ਇਸ ਅਧਿਐਨ ਦਾ ਹਿੱਸਾ ਬਣਨ ਲਈ ਆਪਣੀ ਸਹਿਮਤੀ ਦਿੰਦਾ ਹਾਂ।","ageCheckboxLabel":"ਮੈਂ 18 ਸਾਲ ਜਾਂ ਇਸ ਤੋਂ ਵੱਧ ਦਾ ਹਾਂ","voluntaryCheckboxLabel":"ਇਸ ਅਧਿਐਨ ਲਈ ਲੋੜੀਂਦੀ ਜਾਣਕਾਰੀ ਖ਼ੁਦਮੁਖ਼ਤਿਆਰ ਦਿੱਤੀ ਜਾ ਰਹੀ ਹੈ।"}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='pa';
UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"தகவல் தெரிவித்த ஒப்புதல் படிவம்","projectDetails":{"projectTitle":{"label":"திட்டத்தின் தலைப்பு","value":"மார்பக புற்றுநோய் அபாயத்தை கணிக்க AI உதவியுள்ள கருவி"},"iecReference":{"label":"IEC குறிப்பு எண்","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"IEC ஒப்புதல் தேதி","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"IEC ஒப்புதல் காலம்","value":"மார்ச் 2028 வரை"}},"sections":[{"heading":"தன்னார்வ பங்கேற்பு","paragraphs":[{"text":"இந்த ஆய்வில் உங்கள் பங்கேற்பு தன்னார்வமானது. நீங்கள் எந்த நேரத்திலும் இந்த ஆய்வில் அல்லது இந்த ஆய்வின் எந்தப் பகுதியிலும் பங்கேற்க மறுக்கலாம். அதேபோல், ஆராய்ச்சியாளர் எந்த நேரத்திலும் ஒரு காரணத்தை வழங்காமல் உங்கள் ஆய்வில் பங்கேற்பதை நிறுத்த உரிமை உண்டு. உங்கள் பங்கேற்பை திரும்பப் பெறுவது அல்லது நிறுத்துவது உங்கள் நிறுவனம் / பல்கலைக்கழகம் / மருத்துவமனையுடனான உங்கள் உறவுகளை பாதிக்காது அல்லது நீங்கள் பெறும் பராமரிப்பை பாதிக்காது. இந்த ஆய்வின் போது எந்த நேரத்திலும் இந்த ஆய்வைப் பற்றி கேள்விகளைக் கேட்க உங்களை ஊக்குவிக்கிறோம்."}]},{"heading":"இந்த ஆய்வின் ஒரு பகுதியாக சேகரிக்கப்பட்ட தகவல்கள்","paragraphs":[{"text":"மக்கள்தொகை, வாழ்க்கை முறை, குடும்ப வரலாறு, மாதவிடாய் மற்றும் இனப்பெருக்க சுகாதாரத் தகவல் - அவசியம்"},{"text":"மாம்மோகிராமிகள் மற்றும் அறிக்கை (தேவை)"},{"text":"அல்ட்ரா சவுண்ட் மற்றும்/அல்லது பியோப்சி அறிக்கை (விரும்பினால்)"}]},{"heading":"இரகசியத்தன்மை மற்றும் தரவு பாதுகாப்பு","paragraphs":[{"text":"தரவு அநாமதேயமாக்கல்ஃ இந்த ஆய்வில் சேகரிக்கப்பட்ட அனைத்து தகவல்களும் உங்கள் தனியுரிமையை உறுதிப்படுத்த ஒரு மாற்றமுடியாத அநாமதேய முறையில் சேகரிக்கப்படும், செயலாக்கப்படும் மற்றும் சேமிக்கப்படும். சேகரிக்கப்பட்ட தகவல்களை சேமிப்பது டிஜிட்டல் தனிப்பட்ட தரவு பாதுகாப்பு (டிபிடிபி) சட்டத்தின் தரங்களுக்கு இணங்குகிறது."},{"text":"சேகரிக்கப்பட்ட தரவுகளை எதிர்கால ஆராய்ச்சியில் பயன்படுத்தப்படும், இதில் பிற அடித்தள மாதிரிகள் உருவாக்கப்படும்."},{"text":"உரிமைகள்ஃ உங்கள் தனிப்பட்ட தரவை அணுகவும் திருத்தவும் மற்றும் ஆராய்ச்சி செயலாக்கத்திற்கான உங்கள் ஒப்புதலை எந்த நேரத்திலும் திரும்பப் பெறவும் உங்களுக்கு உரிமை உண்டு. திரும்பப் பெறுவதற்கான முடிவு உங்களுக்கு வழக்கமான மருத்துவ சிகிச்சையை பாதிக்காது."},{"text":"பாதுகாத்தல்ஃ உங்கள் பெயரிடப்படாத தரவு மற்றும் மாதிரிகள் சட்டபூர்வமான ஆராய்ச்சிக்கு பயனுள்ளதாக இருக்கும் வரை, DPDP சட்டம் மற்றும் பிற சட்ட அல்லது ஒழுங்குமுறை கடமைகளுக்கு ஏற்ப, தேவையான பாதுகாப்புகள் இருக்கும் வரை சேமிக்கப்படலாம்."},{"text":"நீங்கள் ஆய்வில் இருந்து விலகி உள்ள ஒருவருடன் பேச விரும்பினால், ஒப்புதலை திரும்பப் பெறவும், நீங்கள் நிறுவன நெறிமுறைக் குழுவை (IEC) தொடர்பு கொள்ளலாம்"},{"text":"பெயர்ஃ டாக்டர் ஸ்ரீ வித்யா ஜகதிஷ், ஐ. இ. சி செயலாளர், TANUH"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"பங்கேற்பாளரின் ஒப்புதல்","declaration":"நான் பங்கேற்பு தகவல் தாளைப் படித்து புரிந்து கொண்டேன், இந்த ஆய்வில் தன்னார்வ பங்கேற்பதை உறுதிப்படுத்தினேன். கேள்விகள் கேட்க எனக்கு வாய்ப்பு கிடைத்தது, என் கேள்விகளுக்கு திருப்திகரமாக பதிலளிக்கப்பட்டது. எனது ஒப்புதலை எப்போது வேண்டுமானாலும் திரும்பப் பெறவும், பங்கேற்பதை மறுக்கவும் எனக்கு உரிமை உண்டு என்பதை நான் புரிந்துகொள்கிறேன். இந்த ஆய்வில் பங்கேற்க நான் ஒப்புக்கொள்கிறேன்.","ageCheckboxLabel":"எனக்கு 18 வயது அல்லது அதற்கு மேற்பட்ட வயது","voluntaryCheckboxLabel":"இந்த ஆய்வுக்கு தேவையான தகவல்கள் தன்னார்வமாக வழங்கப்படுகின்றன."}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='ta';
UPDATE participant_information_translations SET content_json=JSON_SET(content_json, '$.informedConsent', CAST('{"title":"సమాచార సమ్మతి రూపం","projectDetails":{"projectTitle":{"label":"ప్రాజెక్టు పేరు","value":"రొమ్ము క్యాన్సర్ ప్రమాదాన్ని అంచనా వేయడానికి AI సహాయపడింది"},"iecReference":{"label":"ఐఈసి రిఫరెన్స్ నంబర్","value":"Clinicom vide letter no: 02434 dated 13-Jan-2026"},"iecApprovalDate":{"label":"ఐఈసి ఆమోదం తేదీ","value":"13-Jan-2026"},"iecApprovalDuration":{"label":"ఐఈసీ ఆమోదం పొడవు","value":"2028 మార్చి వరకు"}},"sections":[{"heading":"స్వచ్ఛందంగా పాల్గొనడం","paragraphs":[{"text":"ఈ అధ్యయనంలో మీ పాల్గొనడం స్వచ్ఛందమైనది. మీరు ఈ అధ్యయనంలో లేదా ఈ అధ్యయనంలోని ఏ భాగంలోనైనా ఎప్పుడైనా పాల్గొనడానికి నిరాకరించవచ్చు. అదేవిధంగా పరిశోధకుడు కూడా ఒక కారణం ఇవ్వకుండా ఎప్పుడైనా ప్రయోగంలో మీ పాల్గొనడాన్ని నిలిపివేయడానికి హక్కు కలిగి ఉంటాడు. మీ పాల్గొనడాన్ని ఉపసంహరించుకునే లేదా నిలిపివేయాలనే నిర్ణయం మీ సంస్థ / విశ్వవిద్యాలయం / ఆసుపత్రితో మీ సంబంధాలను ప్రభావితం చేయదు లేదా మీరు అందుకున్న సంరక్షణను ప్రభావితం చేయదు. మీరు ఈ అధ్యయనంలో ఎప్పుడైనా ప్రశ్నలు అడగమని ప్రోత్సహిస్తారు."}]},{"heading":"ఈ అధ్యయనంలో భాగంగా సేకరించిన సమాచారం","paragraphs":[{"text":"జనాభా, జీవనశైలి, కుటుంబ చరిత్ర, నెలవారీ మరియు పునరుత్పత్తి ఆరోగ్య సమాచారం - అవసరం"},{"text":"నివేదికతో పాటు మామోగ్రామ్లు (అవసరం)"},{"text":"అల్ట్రాసౌండ్ మరియు/లేదా బయోప్సీ నివేదిక (ఐచ్ఛికం)"}]},{"heading":"గోప్యత మరియు డేటా రక్షణ","paragraphs":[{"text":"డేటా అనామకతః ఈ అధ్యయనంలో సేకరించిన మొత్తం సమాచారం మీ గోప్యతను నిర్ధారించడానికి తిరగలేని విధంగా అనామకతతో సేకరించబడుతుంది, ప్రాసెస్ చేయబడుతుంది మరియు నిల్వ చేయబడుతుంది. సేకరించిన సమాచారం నిల్వ డిజిటల్ వ్యక్తిగత డేటా రక్షణ (DPDP) చట్టం ప్రమాణాలకు అనుగుణంగా ఉంటుంది."},{"text":"సేకరించిన డేటా భవిష్యత్తులో పరిశోధనలో ఉపయోగించబడుతుంది, ఇందులో ఇతర ఫౌండేషన్ నమూనాల అభివృద్ధి కూడా ఉంటుంది."},{"text":"హక్కులుః మీ వ్యక్తిగత డేటాకు ప్రాప్యత మరియు సరిదిద్దడానికి మరియు పరిశోధన ప్రాసెసింగ్ కోసం మీ సమ్మతిని ఎప్పుడైనా ఉపసంహరించుకునే హక్కు మీకు ఉంది. ఉపసంహరించుకునే నిర్ణయం మీకు సాధారణ క్లినికల్ సంరక్షణను ప్రభావితం చేయదు."},{"text":"నిలుపుదలః మీ చిత్తశుద్ధిలేనిగా అనామక డేటా మరియు నమూనాలను చట్టబద్ధమైన పరిశోధన కోసం ఉపయోగపడేంత కాలం మరియు అవసరమైన రక్షణ చర్యలు అమలులో ఉన్నంత కాలం, DPDP చట్టం మరియు ఇతర చట్టపరమైన లేదా నియంత్రణ బాధ్యతలకు అనుగుణంగా నిల్వ చేయవచ్చు."},{"text":"మీరు అధ్యయనానికి సంబంధించి ఒక వ్యక్తితో మాట్లాడాలనుకుంటే మరియు మీ సమ్మతిని ఉపసంహరించుకోవాలనుకుంటే, మీరు సంస్థాగత నైతిక కమిటీ (IEC) ను సంప్రదించవచ్చు"},{"text":"పేరు: డాక్టర్ శ్రీ విద్యా జగదీష్, ఐఇసి కార్యదర్శి, తన్యుహ"},{"text":"Email: secretary.iec@tanuh.ai"},{"text":"Phone# 080 - 2293 4106 / 2293 4107"}]}],"participantConsentHeading":"పాల్గొనేవారి సమ్మతి","declaration":"నేను ఈ అధ్యయనంలో స్వచ్ఛందంగా పాల్గొనడాన్ని ధృవీకరించాను. నాకు ప్రశ్నలు అడగడానికి అవకాశం లభించింది. నా ప్రశ్నలన్నింటికీ నా సంతృప్తికి సమాధానం లభించింది. నా సమ్మతిని ఎప్పుడైనా ఉపసంహరించుకునే హక్కు నాకు ఉందని మరియు పాల్గొనడానికి నిరాకరించే హక్కు నాకు ఉందని నేను అర్థం చేసుకున్నాను. ఈ అధ్యయనంలో పాల్గొనడానికి నా సమ్మతిని ఇస్తున్నాను.","ageCheckboxLabel":"నా వయసు 18 సంవత్సరాలు లేదా అంతకంటే ఎక్కువ","voluntaryCheckboxLabel":"ఈ అధ్యయనానికి అవసరమైన సమాచారం స్వచ్ఛందంగా అందించబడుతోంది."}' AS JSON)), updated_at=CURRENT_TIMESTAMP WHERE version_number=2 AND language_code='te';

SELECT language_code,
       JSON_UNQUOTE(JSON_EXTRACT(content_json, '$.informedConsent.title')) AS consent_title,
       JSON_LENGTH(JSON_EXTRACT(content_json, '$.informedConsent.sections')) AS section_count,
       JSON_UNQUOTE(JSON_EXTRACT(content_json, '$.informedConsent.ageCheckboxLabel')) AS age_confirmation
FROM participant_information_translations
WHERE version_number=2
ORDER BY language_code;
-- Deliberately no COMMIT.
